package com.jarvis.nextgen;import android.app.*;import android.content.*;import android.os.*;
public final class JarvisMicForegroundService extends Service{public int onStartCommand(Intent i,int f,int id){if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("jarvis_voice","JARVIS Assistant",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(ch);Notification n=new Notification.Builder(this,"jarvis_voice").setContentTitle("JARVIS").setContentText("Голосовой режим активен").setSmallIcon(android.R.drawable.ic_btn_speak_now).build();startForeground(11,n);}return START_NOT_STICKY;}public IBinder onBind(Intent i){return null;}}
